<template>
  <div class="tree-node">
    <!-- Node Header -->
    <div
      class="d-flex align-items-center gap-2 p-2 rounded border bg-white mb-1"
      :style="{ paddingLeft: `${depth * 1.5}rem` }"
    >
      <!-- Toggle -->
      <button
        v-if="element.children && element.children.length > 0"
        @click="expanded = !expanded"
        class="btn btn-sm btn-light p-0"
        style="width:24px;height:24px"
      >
        <span :class="expanded ? 'rotate-90 d-inline-block' : ''">▶</span>
      </button>
      <div v-else style="width:24px"></div>

      <!-- Content -->
      <div class="d-flex align-items-center gap-2 flex-grow-1 overflow-hidden">
        <span class="badge bg-primary text-monospace">{{ element.tag }}</span>

        <span class="text-muted small text-truncate" style="max-width:150px">
          {{ getPreview() }}
        </span>

        <span v-if="element.idAttr" class="badge bg-warning text-dark">
          #{{ element.idAttr }}
        </span>

        <span v-if="element.classes" class="badge bg-info text-dark">
          .{{ element.classes.split(' ')[0] }}
        </span>
      </div>

      <!-- Actions -->
      <div class="d-flex gap-1">
        <button
          @click="$emit('add-child', { parentPath, tag: 'div' })"
          class="btn btn-sm btn-outline-success"
        >
          ➕
        </button>

        <button
          @click="$emit('edit', { element })"
          class="btn btn-sm btn-outline-primary"
        >
          ✏️
        </button>

        <button
          @click="$emit('duplicate', { parentPath, index })"
          class="btn btn-sm btn-outline-secondary"
        >
          📋
        </button>

        <button
          @click="$emit('delete', { parentPath, index })"
          class="btn btn-sm btn-outline-danger"
        >
          <i class="bi bi-trash"></i>
        </button>
      </div>
    </div>

    <!-- Children -->
    <transition name="fade">
      <div v-if="expanded && element.children?.length" class="d-flex flex-column gap-1">
<ElementTreeNode
  v-for="(child, idx) in element.children"
  :key="child.id"
  :element="child"
  :parentPath="`${parentPath}-child-${idx}`"
  :index="idx"
  :depth="depth + 1"
  @add-child="$emit('add-child', $event)"
  @edit="$emit('edit', $event)"
  @delete="$emit('delete', $event)"
  @duplicate="$emit('duplicate', $event)"
/>
      </div>
    </transition>

    <!-- Hint -->
    <div
      v-if="!expanded && element.children?.length"
      class="small text-muted fst-italic bg-light rounded px-2 py-1 mb-1"
      :style="{ paddingLeft: `${depth * 1.5 + 2}rem` }"
    >
      {{ element.children.length }} child{{ element.children.length !== 1 ? 'ren' : '' }}
    </div>
  </div>
</template>

<script>
export default {
  name: 'ElementTreeNode',
  props: {
    element: Object,
    parentPath: String,
    index: Number,
    depth: Number,
  },
  emits: ['add-child', 'edit', 'delete', 'duplicate'],
  data() {
    return {
      expanded: true,
    };
  },
  methods: {
    getPreview() {
      if (this.element.idAttr) return '';
      const content = this.element.content || '';
      const preview = content.substring(0, 30);
      return preview ? `"${preview}${content.length > 30 ? '...' : ''}"` : '';
    },
  },
};
</script>

<style scoped>
.rotate-90 {
  transform: rotate(90deg);
}
.fade-enter-active,
.fade-leave-active {
  transition: all 0.2s ease;
}
.fade-enter-from,
.fade-leave-to {
  opacity: 0;
  transform: translateY(-5px);
}
</style>