<template>
  <div class="d-flex flex-column vh-100 bg-light">

    <!-- HEADER -->
    <div class="d-flex justify-content-between align-items-center p-3 border-bottom bg-white">
      <div>
        <h4 class="mb-0">🏗️ Page Builder</h4>
        <small class="text-muted">Drag. Nest. Export.</small>
      </div>

      <div class="d-flex gap-2">
        <button @click="clearAll" class="btn btn-secondary btn-sm">Clear</button>
        <button @click="exportCode" class="btn btn-primary btn-sm">Export HTML</button>
      </div>
    </div>

    <!-- MAIN -->
    <div class="d-flex flex-grow-1 overflow-hidden">

      <!-- LEFT -->
      <div class="border-end bg-white d-flex flex-column" style="width:35%">
        <div class="d-flex justify-content-between align-items-center p-3 border-bottom bg-light">
          <h6 class="mb-0">🌳 Element Structure</h6>
          <button @click="addRootElement" class="btn btn-success btn-sm">+ Add</button>
        </div>

        <div class="flex-grow-1 overflow-auto p-2">
          <div v-if="elements.length === 0" class="text-center text-muted mt-5">
            <div style="font-size:2rem">📦</div>
            <div>No elements</div>
          </div>

<ElementTreeNode
  v-for="(element, idx) in elements"
  :key="element.id"
  :element="element"
  :parentPath="`root-${idx}`"
  :index="idx"
  :depth="0"
  @add-child="addChildElement"
  @edit="editElement"
  @delete="deleteElement"
  @duplicate="duplicateElement"
/>
        </div>
      </div>

      <!-- RIGHT -->
      <div class="flex-grow-1 d-flex flex-column bg-white">

        <!-- TABS -->
        <div class="nav nav-tabs">
          <button
            class="nav-link"
            :class="{ active: activeTab === 'code' }"
            @click="activeTab = 'code'"
          >📝 Code</button>

          <button
            class="nav-link"
            :class="{ active: activeTab === 'preview' }"
            @click="activeTab = 'preview'"
          >👁️ Preview</button>
        </div>

        <!-- CODE -->
        <div v-if="activeTab === 'code'" class="d-flex flex-column flex-grow-1">
          <div class="p-2 border-bottom bg-light">
            <button @click="copyCode" class="btn btn-outline-secondary btn-sm me-1">Copy</button>

                      <button @click="toggleEditCode" class="btn btn-outline-primary btn-sm">
  {{ isCodeEditable ? 'Save' : 'Edit' }}
</button>
          </div>


          <div class="flex-grow-1 bg-dark text-light p-3 overflow-auto">
<pre
  ref="codeEditor"
  :contenteditable="isCodeEditable"
  @input="updateCode"
  @keydown="saveCursorPosition"
  @click="saveCursorPosition"
  class="flex-grow-1 bg-dark text-light p-3 overflow-auto"
  style="direction: ltr; unicode-bidi: embed;"
></pre>

          </div>
        </div>

        <!-- PREVIEW -->
        <div v-if="activeTab === 'preview'" class="d-flex flex-column flex-grow-1">
          <div class="p-2 border-bottom bg-light">
            <button @click="refreshPreview" class="btn btn-outline-secondary btn-sm">🔄 Refresh</button>
          </div>

          <iframe
            ref="previewFrame"
            :srcdoc="previewHtml"
            class="flex-grow-1 border-0"
          ></iframe>
        </div>

      </div>
    </div>

    <!-- MODAL -->
    <div v-if="editingElement" class="modal fade show d-block" tabindex="-1">
      <div class="modal-dialog modal-lg modal-dialog-centered">
        <div class="modal-content">

          <div class="modal-header">
            <h5 class="modal-title">Edit {{ editingElement.element.tag }}</h5>
            <button class="btn-close" @click="editingElement = null"></button>
          </div>

          <div class="modal-body">

            <!-- raw editor-->
             <div v-if="editingElement && !isVoidElement(editingElement.element.tag)" class="mb-3">
  <label class="form-label">Content / Raw HTML</label>
  <textarea
    v-model="editingElement.element.rawHtml"
    class="form-control"
    placeholder="Paste raw HTML here"
    rows="6"
  ></textarea>
  <small class="text-muted">Paste raw HTML (Bootstrap markup works)</small>
</div>

             <!-- raw editor -->
            <div class="mb-3">
              <label class="form-label">Tag</label>
              <select v-model="editingElement.element.tag" class="form-select">
                <option>div</option><option>section</option><option>p</option>
                <option>h1</option><option>h2</option><option>button</option>
                <option>a</option><option>img</option><option>input</option>
              </select>
            </div>

            <div v-if="!isVoidElement(editingElement.element.tag)" class="mb-3">
              <label class="form-label">Content</label>
              <textarea v-model="editingElement.element.content" class="form-control"></textarea>
            </div>

            <div v-if="editingElement.element.tag === 'img'" class="mb-3">
  <label class="form-label">Image URL (src)</label>
  <input v-model="editingElement.element.src" type="text" class="form-control" placeholder="https://example.com/image.jpg">
</div>

<div v-if="editingElement.element.tag === 'img'" class="mb-3">
  <label class="form-label">Alt Text</label>
  <input v-model="editingElement.element.alt" type="text" class="form-control" placeholder="Description of image">
</div>

            <div class="row">
              <div class="col">
                <input v-model="editingElement.element.idAttr" class="form-control" placeholder="ID">
              </div>
              <div class="col">
                <input v-model="editingElement.element.classes" class="form-control" placeholder="Classes">
              </div>
            </div>

          </div>

          <div class="modal-footer">
            <button class="btn btn-secondary" @click="editingElement = null">Cancel</button>
            <button class="btn btn-primary" @click="saveEdit">Save</button>
          </div>

        </div>
      </div>
    </div>

    <div v-if="editingElement" class="modal-backdrop fade show"></div>

  </div>
</template>

<script>
import ElementTreeNode from './ElementTreeNode.vue';

export default {
  name: 'StaticPageGenerator',
  components: {
    ElementTreeNode,
  },
  data() {
    return {
      elements: [],
      nextId: 1,
      activeTab: 'preview',
      editingElement: null,
      isCodeEditable: false,
      editedCode: '',
      cursorPos: 0,
    };
  },
  computed: {
    generatedCode() {
      const html = this.elements.map(el => this.renderElement(el)).join('\n');
      return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Generated Page</title>
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet">
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: system-ui, -apple-system, sans-serif; padding: 20px; background: #f5f5f5; }
    .page-container { max-width: 1200px; margin: 0 auto; background: white; padding: 20px; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
  </style>
</head>
<body>
  <div class="page-container">
${html.split('\n').map(line => '    ' + line).join('\n')}
  </div>
  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"><\/script>
</body>
</html>`;
    },
    previewHtml() {
      const html = this.elements.map(el => this.renderElement(el)).join('\n');
      return `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet">
  <style>
    body { 
      font-family: system-ui, sans-serif; 
      padding: 20px; 
      background: #f5f5f5; 
      margin: 0;
    }
    .preview-wrapper { 
      background: white; 
      padding: 20px; 
      border-radius: 12px; 
      box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    }
  </style>
</head>
<body>
  <div class="preview-wrapper">
${html.split('\n').map(line => '    ' + line).join('\n')}
  </div>
  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"><\/script>
  <script>
    document.addEventListener('DOMContentLoaded', function() {
      var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'))
      var tooltipList = tooltipTriggerList.map(function (el) { return new bootstrap.Tooltip(el) })
      var popoverTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="popover"]'))
      var popoverList = popoverTriggerList.map(function (el) { return new bootstrap.Popover(el) })
    });
  <\/script>
</body>
</html>`;
    },
     bodyOnlyHtml() {           // new one for Element Structure / Code panel
    return this.elements.map(el => this.renderElement(el)).join('\n');
  }
  },
  watch: {
    elements: {
      deep: true,
      handler() {
        this.refreshPreview();
      },
    },
  },

  watch: {
  activeTab(newTab) {
    if (newTab === 'code') {
      this.$nextTick(() => {
        const editor = this.$refs.codeEditor;
        if (editor && !this.isCodeEditable) {
          editor.innerText = this.generatedCode; // fill pre initially
        }
      });
    }
  },
},

  methods: {
    createNewElement(tag = 'div') {
      return {
        id: this.nextId++,
        tag,
        content: '',
        idAttr: '',
        classes: '',
        href: '',
        src: '',
        alt: '',
        type: '',
        dataBsToggle: '',
        dataBsTarget: '',
        styles: [],
        children: [],
      };
    },
    addRootElement() {
      this.elements.push(this.createNewElement());
    },
    addChildElement({ parentPath, tag }) {
      const parent = this.findElementByPath(parentPath);
      if (parent) {
        parent.children.push(this.createNewElement(tag || 'div'));
      }
    },
    findElementByPath(path) {
      const parts = path.split('-');
      if (parts[0] !== 'root') return null;

      let current = this.elements[parseInt(parts[1])];
      for (let i = 2; i < parts.length; i += 2) {
        if (current && parts[i] === 'child') {
          current = current.children[parseInt(parts[i + 1])];
        }
      }
      return current;
    },
    editElement({ element }) {
      this.editingElement = {
        element: JSON.parse(JSON.stringify(element)),
        originalElement: element,
      };
    },
saveEdit() {
  if (!this.editingElement) return;

  const el = this.editingElement.element;

  if (el.rawHtml) {
    const parsedChildren = this.parseHtmlToChildren(el.rawHtml);
     el.children = parsedChildren;
    el.rawHtml = '';
  }

  Object.assign(this.editingElement.originalElement, el);
  this.editingElement = null;
},
deleteElement({ parentPath, index }) {
  const pathParts = parentPath.split('-');

  // Root level
  if (pathParts.length === 2 && pathParts[0] === 'root') {
    this.elements.splice(index, 1);
    return;
  }

  // Find the actual parent of the element
  const parentPathParts = pathParts.slice(0, -2).join('-');
  const parent = this.findElementByPath(parentPathParts);

  if (parent && parent.children) {
    parent.children.splice(index, 1);
  }
},
duplicateElement({ parentPath, index }) {
  const pathParts = parentPath.split('-');

  // Root level
  if (pathParts.length === 2 && pathParts[0] === 'root') {
    const original = this.elements[index];
    const duplicate = JSON.parse(JSON.stringify(original));
    duplicate.id = this.nextId++;
    this.elements.splice(index + 1, 0, duplicate);
    return;
  }

  // Nested children
  const parentPathParts = pathParts.slice(0, -2).join('-');
  const parent = this.findElementByPath(parentPathParts);

  if (parent && parent.children) {
    const original = parent.children[index];
    const duplicate = JSON.parse(JSON.stringify(original));
    duplicate.id = this.nextId++;
    parent.children.splice(index + 1, 0, duplicate);
  }
},
    addStyleInput() {
      if (this.editingElement) {
        this.editingElement.element.styles.push({ property: '', value: '' });
      }
    },
    removeStyle(index) {
      if (this.editingElement) {
        this.editingElement.element.styles.splice(index, 1);
      }
    },
    isVoidElement(tag) {
      const voidTags = ['img', 'input', 'br', 'hr', 'meta', 'link'];
      return voidTags.includes(tag);
    },
    renderElement(el) {
      let attrs = '';
      if (el.idAttr) attrs += ` id="${this.escapeHtml(el.idAttr)}"`;
      if (el.classes) attrs += ` class="${this.escapeHtml(el.classes)}"`;
      if (el.href && el.tag === 'a') attrs += ` href="${this.escapeHtml(el.href)}"`;
      if (el.src && el.tag === 'img') attrs += ` src="${this.escapeHtml(el.src)}"`;
      if (el.alt && el.tag === 'img') attrs += ` alt="${this.escapeHtml(el.alt)}"`;
      if (el.type && (el.tag === 'input' || el.tag === 'button')) attrs += ` type="${this.escapeHtml(el.type)}"`;
      if (el.dataBsToggle) attrs += ` data-bs-toggle="${this.escapeHtml(el.dataBsToggle)}"`;
      if (el.dataBsTarget) attrs += ` data-bs-target="${this.escapeHtml(el.dataBsTarget)}"`;

      const validStyles = el.styles.filter(s => s.property.trim() && s.value.trim());
      if (validStyles.length > 0) {
        const styleStr = validStyles.map(s => `${s.property.trim()}: ${s.value.trim()}`).join('; ');
        attrs += ` style="${this.escapeHtml(styleStr)}"`;
      }

      if (this.isVoidElement(el.tag)) {
        return `<${el.tag}${attrs}>`;
      }

      let childrenHtml = '';
      if (el.children && el.children.length > 0) {
        childrenHtml = el.children.map(child => this.renderElement(child)).join('\n');
      }

     const innerContent = childrenHtml || el.rawHtml || el.content || '';

      return `<${el.tag}${attrs}>${innerContent}</${el.tag}>`;
    },
    escapeHtml(str) {
      if (!str) return '';
      return str
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    },
    clearAll() {
      if (confirm('Clear all elements? This cannot be undone.')) {
        this.elements = [];
        this.nextId = 1;
      }
    },
    copyCode() {
      navigator.clipboard.writeText(this.generatedCode);
      alert('Code copied to clipboard!');
    },
    exportCode() {
      const blob = new Blob([this.generatedCode], { type: 'text/html' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'generated-page.html';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    },
    refreshPreview() {
      if (this.$refs.previewFrame) {
        this.$refs.previewFrame.srcdoc = this.previewHtml;
      }
    },

    parseTableHtml(html) {
  const wrapper = document.createElement('div');
  wrapper.innerHTML = html;

  const parseNode = (node) => {
    const el = {
      id: this.nextId++,
      tag: node.tagName.toLowerCase(),
      content: '',
      idAttr: node.id || '',
      classes: node.className || '',
      children: [],
      href: node.href || '',
      src: node.src || '',
      alt: node.alt || '',
      type: node.type || '',
      dataBsToggle: node.dataset.bsToggle || '',
      dataBsTarget: node.dataset.bsTarget || '',
      styles: [],
    };

    // If node has no children, store innerHTML as content
    if (node.children.length === 0) {
      el.content = node.innerHTML;
    } else {
      Array.from(node.children).forEach((child) => {
        el.children.push(parseNode(child));
      });
    }
    return el;
  };

  const children = [];
  Array.from(wrapper.children).forEach((child) => {
    children.push(parseNode(child));
  });

  return children;
},

parseHtmlToChildren(html) {
  const wrapper = document.createElement('div');
  wrapper.innerHTML = html;

  const parseNode = (node) => {
    const el = {
      id: this.nextId++,
      tag: node.tagName.toLowerCase(),
      content: '',
      idAttr: node.id || '',
      classes: node.className || '',
      children: [],
      href: node.href || '',
      src: node.src || '',
      alt: node.alt || '',
      type: node.type || '',
      dataBsToggle: node.dataset.bsToggle || '',
      dataBsTarget: node.dataset.bsTarget || '',
      styles: [],
    };

    Array.from(node.childNodes).forEach((child) => {
      if (child.nodeType === 1) { // element
        el.children.push(parseNode(child));
      } else if (child.nodeType === 3) { // text node
        const text = child.textContent.trim();
        if (text) el.content += text;
      }
    });

    return el;
  };

  return Array.from(wrapper.children).map(parseNode);
},

toggleEditCode() {
  const editor = this.$refs.codeEditor;
  if (!this.isCodeEditable) {
    this.editedCode = this.generatedCode;
    editor.innerText = this.editedCode;
  } else {
    this.loadEditedCodeIntoElements(this.editedCode);
  }
  this.isCodeEditable = !this.isCodeEditable;
},

updateCode(event) {
  const el = event.target;
  this.editedCode = el.innerText;
  this.$nextTick(() => this.restoreCursor());
},

saveCursorPosition(event) {
  const sel = window.getSelection();
  if (sel.rangeCount > 0) {
    const range = sel.getRangeAt(0);
    this.cursorPos = range.startOffset;
  }
},

restoreCursor() {
  const el = this.$refs.codeEditor;
  el.focus();
  const sel = window.getSelection();
  const range = document.createRange();
  range.setStart(el.firstChild || el, this.cursorPos);
  range.collapse(true);
  sel.removeAllRanges();
  sel.addRange(range);
},

loadEditedCodeIntoElements(html) {
  const wrapper = document.createElement('div');
  wrapper.innerHTML = html;

  const parseNode = (node) => {
    const el = {
      id: this.nextId++,
      tag: node.tagName.toLowerCase(),
      content: '',
      idAttr: node.id || '',
      classes: node.className || '',
      children: [],
      href: node.href || '',
      src: node.src || '',
      alt: node.alt || '',
      type: node.type || '',
      dataBsToggle: node.dataset.bsToggle || '',
      dataBsTarget: node.dataset.bsTarget || '',
      styles: [],
    };

    Array.from(node.childNodes).forEach((child) => {
      if (child.nodeType === 1) {
        el.children.push(parseNode(child));
      } else if (child.nodeType === 3) {
        const text = child.textContent.trim();
        if (text) el.content += text;
      }
    });

    return el;
  };

  this.elements = Array.from(wrapper.children).map(parseNode);
  this.refreshPreview();
},


  },



  mounted() {
    this.addRootElement();
  },
};
</script>

